sections.code:
CREATE INDEX u3_enrol_course_mark
ON U3Enrolment(course_code, mark);

SELECT student_id, mark
FROM U3Enrolment
WHERE course_code = 'DB101' AND mark >= 80
ORDER BY mark, student_id;

